def countOfSubstrings(S, K):
    char_count = {}
    count = 0

    # Initialize the first window
    for i in range(K):
        char_count[S[i]] = char_count.get(S[i], 0) + 1

    # Check the first window
    if len(char_count) == K - 1:
        count += 1

    # Slide the window
    for i in range(K, len(S)):
